-- 2. PRODUCT itself -- ID, name, and building number all change together.
UPDATE PRODUCT P JOIN PRODUCT_ID_RENAME_MAP M ON P.PRODUCT_ID = M.OLD_ID
SET P.PRODUCT_ID = M.NEW_ID,
    P.PRODUCT_NAME = M.NEW_NAME,
    P.BUILDING_NUMBER = M.NEW_BUILDING;
-- expect: 68 rows affected

