-- All 68 should now show their new IDs/names/building numbers.
SELECT PRODUCT_ID, PRODUCT_NAME, BUILDING_NUMBER, FLOOR_NUMBER, APARTMENT_STATUS_ID
FROM PRODUCT
WHERE PROJECT_ID IN ('10339', '113') AND PRODUCT_ID REGEXP '^[0-9]+$';
-- expect: 0 rows (no numeric-sequence apartment IDs left for these two projects)

SELECT PRODUCT_ID, PRODUCT_NAME, BUILDING_NUMBER, FLOOR_NUMBER
FROM PRODUCT
WHERE PROJECT_ID = '10339'
ORDER BY PRODUCT_ID;
-- expect: 48 rows, IDs A-01..A-08, A-11..A-18, A-21..A-28, A-31..A-38, A-41..A-48, A-51..A-58

SELECT PRODUCT_ID, PRODUCT_NAME, BUILDING_NUMBER, FLOOR_NUMBER
FROM PRODUCT
WHERE PROJECT_ID = '113' AND PRODUCT_ID REGEXP '^B16[6-9]-[0-9]{2}$'
ORDER BY PRODUCT_ID;
-- expect: 20 rows, the B166-xx/B167-xx/B168-xx/B169-xx set from the mapping above

-- The 2 known sales requests should now point at the new IDs.
SELECT SALES_REQUEST_ID, PRODUCT_ID, STATUS_ID FROM SALES_REQUEST
WHERE SALES_REQUEST_ID IN ('10888', '10889');
-- expect: 10888 -> A-12, 10889 -> A-14

-- Total product count is unchanged (rename only, nothing added/removed).
